   300                  if (log_ctx != NULL) {
   301                      /* print the OID value */
   302                      log_ctx->fn(log_ctx->ctx, "Initialized SECP512R1 signing key with %d bytes.\n", ecdsa_key_data_length);
   303                  }
   304              } else if (log_ctx != NULL) {
   305                  log_ctx->fn(log_ctx->ctx, "SECP512R1 init with %d bytes returns %d.\n", ecdsa_key_data_length, decode_error);
   306              }
   307          }
   308      } else {
   309          decode_error = PTLS_ERROR_INCORRECT_PEM_ECDSA_CURVE;
   310          if (log_ctx != NULL) {
   311              /* print the OID value */
   312              log_ctx->fn(log_ctx->ctx, "Curve is not supported for signatures.\n");
   313          }
   314      }
   315
   316      return decode_error;
   317  }
   318
   319  int ptls_minicrypto_load_private_key(ptls_context_t *ctx, char const *pem_fname)
   320  {
   321      ptls_asn1_pkcs8_private_key_t pkey = {{0}};
   322      int ret = ptls_pem_parse_private_key(pem_fname, &pkey, NULL);
   323
   324      /* Check that this is the expected key type.
   325      * At this point, the minicrypto library only supports ECDSA keys.
   326      * In theory, we could add support for RSA keys at some point.
   327      */
   328      if (ret == 0) {
   329          if (pkey.algorithm_length == sizeof(ptls_asn1_algorithm_ecdsa) &&
   330              memcmp(pkey.vec.base + pkey.algorithm_index, ptls_asn1_algorithm_ecdsa, sizeof(ptls_asn1_algorithm_ecdsa)) == 0) {
   331              ret = ptls_set_ecdsa_private_key(ctx, &pkey, NULL);
   332          } else {
   333              ret = -1;
   334          }
   335      }
   336
   337      return ret;
   338  }
